CREATE OR REPLACE FUNCTION public.create_cotacao_atomic(p_titulo text, p_observacao text DEFAULT NULL::text, p_data_validade date DEFAULT NULL::date, p_origin_type text DEFAULT 'MANUAL'::text, p_origin_ref uuid DEFAULT NULL::uuid, p_itens jsonb DEFAULT '[]'::jsonb, p_fornecedores jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company uuid;
  v_user    uuid;
  v_id      uuid;
  v_codigo  text;
  v_base    int;
  v_elem    jsonb;
  i         int;
BEGIN
  v_company := public.assert_tenant();
  v_user := auth.uid();
  IF v_user IS NULL THEN RAISE EXCEPTION 'PERMISSION_DENIED: não autenticado'; END IF;

  IF NOT public.has_any_permission(v_user, ARRAY['compras:cotacao:create','system:global:manage']) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: compras:cotacao:create';
  END IF;

  IF p_titulo IS NULL OR length(btrim(p_titulo)) = 0 THEN
    RAISE EXCEPTION 'VALIDATION: título obrigatório';
  END IF;
  IF p_origin_type IS NOT NULL AND p_origin_type NOT IN ('MANUAL','ALERTA','REQUISICAO') THEN
    RAISE EXCEPTION 'VALIDATION: origin_type inválido';
  END IF;

  v_base := (SELECT count(*) FROM public.cotacoes WHERE company_id = v_company);
  FOR i IN 1..15 LOOP
    v_codigo := 'COT-' || lpad((v_base + i)::text, 5, '0');
    BEGIN
      INSERT INTO public.cotacoes (company_id, codigo, titulo, observacao, data_validade, origin_type, origin_ref, status, created_by)
      VALUES (v_company, v_codigo, btrim(p_titulo), NULLIF(btrim(coalesce(p_observacao,'')),''), p_data_validade,
              coalesce(p_origin_type,'MANUAL'), p_origin_ref, 'RASCUNHO', v_user)
      RETURNING id INTO v_id;
      EXIT;
    EXCEPTION WHEN unique_violation THEN
      v_id := NULL;
    END;
  END LOOP;
  IF v_id IS NULL THEN RAISE EXCEPTION 'VALIDATION: falha ao gerar código da cotação'; END IF;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(coalesce(p_itens, '[]'::jsonb)) LOOP
    INSERT INTO public.cotacao_itens
      (cotacao_id, company_id, produto_id, produto_nome_snapshot, unidade_snapshot,
       purchase_unit_snapshot, conversion_factor_snapshot, quantidade, observacao)
    VALUES (
      v_id, v_company,
      NULLIF(v_elem->>'produto_id','')::uuid,
      coalesce(NULLIF(btrim(v_elem->>'produto_nome_snapshot'),''), 'Item'),
      NULLIF(v_elem->>'unidade_snapshot',''),
      NULLIF(v_elem->>'purchase_unit_snapshot',''),
      coalesce((v_elem->>'conversion_factor_snapshot')::numeric, 1),
      coalesce((v_elem->>'quantidade')::numeric, 0),
      NULLIF(v_elem->>'observacao','')
    );
  END LOOP;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(coalesce(p_fornecedores, '[]'::jsonb)) LOOP
    INSERT INTO public.cotacao_fornecedores
      (cotacao_id, company_id, supplier_id, supplier_nome_snapshot, whatsapp_snapshot, pedido_minimo_snapshot, status)
    VALUES (
      v_id, v_company,
      NULLIF(v_elem->>'supplier_id','')::uuid,
      coalesce(NULLIF(btrim(v_elem->>'supplier_nome_snapshot'),''), 'Fornecedor'),
      NULLIF(v_elem->>'whatsapp_snapshot',''),
      coalesce((v_elem->>'pedido_minimo_snapshot')::numeric, 0),
      'AGUARDANDO'
    );
  END LOOP;

  RETURN jsonb_build_object('success', true, 'id', v_id, 'codigo', v_codigo);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_purchase_orders_from_cotacao_atomic(p_cotacao_id uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company     uuid;
  v_user        uuid;
  v_cot         record;
  v_forn        record;
  v_order_id    uuid;
  v_total       numeric;
  v_items       int;
  v_orders      int := 0;
  v_total_items int := 0;
  v_order_ids   uuid[] := '{}';
  v_sel_count   int;
BEGIN
  v_company := public.assert_tenant();
  v_user := auth.uid();
  IF v_user IS NULL THEN RAISE EXCEPTION 'PERMISSION_DENIED: não autenticado'; END IF;

  IF NOT public.has_any_permission(v_user, ARRAY['compras:cotacao:close','compras:cotacao:manage','system:global:manage']) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: compras:cotacao:close';
  END IF;

  SELECT id, codigo, titulo, status, updated_at
    INTO v_cot
  FROM public.cotacoes
  WHERE id = p_cotacao_id AND company_id = v_company AND deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;

  IF v_cot.status = 'CONVERTIDA' THEN
    RAISE EXCEPTION 'STATUS_INVALIDO: % (cotação já convertida em pedido)', v_cot.status;
  END IF;
  IF v_cot.status IN ('CANCELADA','ENCERRADA') THEN
    RAISE EXCEPTION 'STATUS_INVALIDO: % (cotação encerrada)', v_cot.status;
  END IF;
  IF p_expected_updated_at IS NOT NULL AND v_cot.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT';
  END IF;

  SELECT count(*) INTO v_sel_count
  FROM public.cotacao_respostas r
  JOIN public.cotacao_fornecedores f ON f.id = r.cotacao_fornecedor_id
  WHERE f.cotacao_id = p_cotacao_id
    AND r.company_id = v_company
    AND r.selecionado = true
    AND r.disponivel = true
    AND r.preco_unitario IS NOT NULL;
  IF v_sel_count = 0 THEN
    RAISE EXCEPTION 'VALIDATION: nenhuma resposta selecionada — gere e salve a sugestão antes de converter';
  END IF;

  FOR v_forn IN
    SELECT f.id, f.supplier_nome_snapshot, f.condicao_pagamento
    FROM public.cotacao_fornecedores f
    WHERE f.cotacao_id = p_cotacao_id
      AND f.company_id = v_company
      AND EXISTS (
        SELECT 1 FROM public.cotacao_respostas r
        WHERE r.cotacao_fornecedor_id = f.id
          AND r.company_id = v_company
          AND r.selecionado = true
          AND r.disponivel = true
          AND r.preco_unitario IS NOT NULL
      )
    ORDER BY f.supplier_nome_snapshot
  LOOP
    SELECT coalesce(sum(r.preco_unitario * i.quantidade), 0) INTO v_total
    FROM public.cotacao_respostas r
    JOIN public.cotacao_itens i ON i.id = r.cotacao_item_id
    WHERE r.cotacao_fornecedor_id = v_forn.id
      AND r.company_id = v_company
      AND r.selecionado = true
      AND r.disponivel = true
      AND r.preco_unitario IS NOT NULL;

    INSERT INTO public.purchase_orders (
      title, type, priority, category, supplier_name, payment_type,
      notes, status, total_estimated, created_by, company_id,
      idempotency_key, origin, origin_ref
    ) VALUES (
      v_cot.codigo || ' — ' || v_forn.supplier_nome_snapshot,
      'FORNECEDOR', 'MEDIA', '',
      v_forn.supplier_nome_snapshot,
      NULLIF(btrim(coalesce(v_forn.condicao_pagamento,'')), ''),
      'Gerado da cotação ' || v_cot.codigo || ' (' || v_cot.titulo || ')',
      'OPEN', coalesce(v_total, 0), v_user, v_company,
      gen_random_uuid(), 'COTACAO', p_cotacao_id::text
    ) RETURNING id INTO v_order_id;

    INSERT INTO public.purchase_order_items (
      order_id, stock_item_id, name_snapshot, unit_snapshot,
      estimated_unit_value, qty_requested,
      purchase_unit_snapshot, purchase_unit_cost_snapshot, conversion_factor_snapshot,
      shopping_status, company_id
    )
    SELECT
      v_order_id,
      i.produto_id,
      i.produto_nome_snapshot,
      coalesce(NULLIF(i.unidade_snapshot,''), 'UN'),
      r.preco_unitario,
      i.quantidade,
      coalesce(NULLIF(i.purchase_unit_snapshot,''), NULLIF(i.unidade_snapshot,''), 'UN'),
      r.preco_unitario,
      coalesce(i.conversion_factor_snapshot, 1),
      'OK',
      v_company
    FROM public.cotacao_respostas r
    JOIN public.cotacao_itens i ON i.id = r.cotacao_item_id
    WHERE r.cotacao_fornecedor_id = v_forn.id
      AND r.company_id = v_company
      AND r.selecionado = true
      AND r.disponivel = true
      AND r.preco_unitario IS NOT NULL;

    GET DIAGNOSTICS v_items = ROW_COUNT;
    v_total_items := v_total_items + v_items;
    v_orders := v_orders + 1;
    v_order_ids := array_append(v_order_ids, v_order_id);

    UPDATE public.cotacao_fornecedores
       SET status = 'FECHADO'
     WHERE id = v_forn.id AND company_id = v_company;

    INSERT INTO public.audit_log (tabela, registro_id, acao, user_id)
    VALUES ('purchase_orders', v_order_id, 'CRIACAO', v_user);
  END LOOP;

  UPDATE public.cotacoes
     SET status = 'CONVERTIDA'
   WHERE id = p_cotacao_id AND company_id = v_company;

  UPDATE public.cotacao_sugestoes s
     SET dados_json = coalesce(s.dados_json, '{}'::jsonb)
                      || jsonb_build_object('generated_order_ids', to_jsonb(v_order_ids))
   WHERE s.id = (
     SELECT id FROM public.cotacao_sugestoes
     WHERE cotacao_id = p_cotacao_id AND company_id = v_company
     ORDER BY created_at DESC
     LIMIT 1
   );

  RETURN jsonb_build_object(
    'success', true,
    'orders', v_orders,
    'items', v_total_items,
    'order_ids', to_jsonb(v_order_ids)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_cotacao_atomic(p_id uuid, p_titulo text, p_observacao text DEFAULT NULL::text, p_data_validade date DEFAULT NULL::date, p_itens jsonb DEFAULT '[]'::jsonb, p_fornecedores jsonb DEFAULT '[]'::jsonb, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company uuid;
  v_user    uuid;
  v_cot     record;
  v_elem    jsonb;
BEGIN
  v_company := public.assert_tenant();
  v_user := auth.uid();

  IF NOT public.has_any_permission(v_user, ARRAY['compras:cotacao:edit','system:global:manage']) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: compras:cotacao:edit';
  END IF;

  SELECT id, status, updated_at INTO v_cot
  FROM public.cotacoes
  WHERE id = p_id AND company_id = v_company AND deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;

  IF v_cot.status NOT IN ('RASCUNHO','EM_COTACAO') THEN
    RAISE EXCEPTION 'STATUS_INVALIDO: % (edição só em RASCUNHO/EM_COTACAO)', v_cot.status;
  END IF;
  IF p_expected_updated_at IS NOT NULL AND v_cot.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT';
  END IF;
  IF p_titulo IS NULL OR length(btrim(p_titulo)) = 0 THEN
    RAISE EXCEPTION 'VALIDATION: título obrigatório';
  END IF;

  UPDATE public.cotacoes
     SET titulo = btrim(p_titulo),
         observacao = NULLIF(btrim(coalesce(p_observacao,'')),''),
         data_validade = p_data_validade
   WHERE id = p_id;

  DELETE FROM public.cotacao_itens WHERE cotacao_id = p_id;
  DELETE FROM public.cotacao_fornecedores WHERE cotacao_id = p_id;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(coalesce(p_itens, '[]'::jsonb)) LOOP
    INSERT INTO public.cotacao_itens
      (cotacao_id, company_id, produto_id, produto_nome_snapshot, unidade_snapshot,
       purchase_unit_snapshot, conversion_factor_snapshot, quantidade, observacao)
    VALUES (
      p_id, v_company,
      NULLIF(v_elem->>'produto_id','')::uuid,
      coalesce(NULLIF(btrim(v_elem->>'produto_nome_snapshot'),''), 'Item'),
      NULLIF(v_elem->>'unidade_snapshot',''),
      NULLIF(v_elem->>'purchase_unit_snapshot',''),
      coalesce((v_elem->>'conversion_factor_snapshot')::numeric, 1),
      coalesce((v_elem->>'quantidade')::numeric, 0),
      NULLIF(v_elem->>'observacao','')
    );
  END LOOP;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(coalesce(p_fornecedores, '[]'::jsonb)) LOOP
    INSERT INTO public.cotacao_fornecedores
      (cotacao_id, company_id, supplier_id, supplier_nome_snapshot, whatsapp_snapshot, pedido_minimo_snapshot, status)
    VALUES (
      p_id, v_company,
      NULLIF(v_elem->>'supplier_id','')::uuid,
      coalesce(NULLIF(btrim(v_elem->>'supplier_nome_snapshot'),''), 'Fornecedor'),
      NULLIF(v_elem->>'whatsapp_snapshot',''),
      coalesce((v_elem->>'pedido_minimo_snapshot')::numeric, 0),
      'AGUARDANDO'
    );
  END LOOP;

  RETURN jsonb_build_object('success', true, 'id', p_id);
END;
$function$
